{
  "providers": {
    "{{provider_key}}": {
      "name": "Streamscope",
      "package": "@opencode/ai/providers/anthropic",
      "settings": {
        "apiKey": "{{api_key}}",
        "baseURL": "{{base_url}}/v1"
      },
      "models": {
{{#each routes}}        "{{model_alias}}": { "name": "{{model_alias}}", "capabilities": { "tools": {{supports_function_calling}}, "input": ["text"{{#if supports_vision}}, "image"{{/if}}{{#if supports_audio_input}}, "audio"{{/if}}{{#if supports_video_input}}, "video"{{/if}}{{#if supports_pdf_input}}, "pdf"{{/if}}], "output": ["text"{{#if supports_audio_output}}, "audio"{{/if}}] }{{#if context_window}}, "limit": { "context": {{context_window}}{{#if max_output_tokens}}, "output": {{max_output_tokens}}{{/if}} }{{/if}} }{{#unless @last}},{{/unless}}
{{/each}}      }
    }
  },
  "model": "{{provider_key}}/{{model_alias}}",
  "share": "disabled",
  "websearch": false,
  "permissions": [
    { "action": "websearch", "resource": "*", "effect": "deny" }
  ],
  "agents": {
    "build": { "model": { "providerID": "{{provider_key}}", "model": "{{model_alias}}" } },
    "plan": { "model": { "providerID": "{{provider_key}}", "model": "{{model_slot_plan}}" } },
    "general": { "model": { "providerID": "{{provider_key}}", "model": "{{model_alias}}" } },
    "explore": { "model": { "providerID": "{{provider_key}}", "model": "{{model_slot_fast}}" } },
    "compaction": { "model": { "providerID": "{{provider_key}}", "model": "{{model_alias}}" } },
    "title": { "model": { "providerID": "{{provider_key}}", "model": "{{model_slot_fast}}" } },
    "summary": { "model": { "providerID": "{{provider_key}}", "model": "{{model_alias}}" } }
  }{{#unless project_scope}},
  "update": "disable",
  "experimental": {
    "policies": [
      { "action": "provider.use", "resource": "{{provider_key}}", "effect": "allow" }
    ]
  }{{/unless}}{{#if mcp_servers}},
  "mcp": {
    "servers": {
{{#each mcp_servers}}      "{{slug}}": {
        "type": "remote",
        "url": "{{url}}",
        "headers": { "Authorization": "Bearer {{api_key}}" },
        "oauth": false,
        "codemode": false
      }{{#unless @last}},{{/unless}}
{{/each}}    }
  }{{/if}}
}

